def find(key):
    f,ph = L[key]; path,off,cite = F[f]
    pages = _pages(path); n = norm(ph)
    for p,t in pages.items():
        if n in t: return p
    ks = sorted(pages)
    for a,b in zip(ks,ks[1:]):
        if n in pages[a]+' '+pages[b]: return a
    return None
def page_label(key):
    p = find(key); off = F[L[key][0]][1]
    if p is None: return None
    if off is None: return f"PDF p.{p}"
    return f"PDF p.{p} (printed p.{p-off})"
if __name__=='__main__':
    bad = 0
    for k in L:
        if page_label(k) is None: bad += 1; print('MISSING', k, L[k][1][:80])
    print('checked', len(L), 'missing', bad)
